// Compute the last COMPLETE week: Sunday 00:00:00 through Saturday 23:59:59
// in store local time (America/New_York). Luxon handles DST automatically,
// so this stays correct when the offset shifts from -04:00 to -05:00.

const now = $now.setZone('America/New_York');

// Luxon weekday: Mon=1 ... Sun=7. Convert so Sun=0 ... Sat=6.
const dayOfWeek = now.weekday % 7;

// Sunday that begins the CURRENT week
const currentWeekStart = now.minus({ days: dayOfWeek }).startOf('day');

// The completed week is the one before it
const weekStart = currentWeekStart.minus({ days: 7 });
const weekEnd = currentWeekStart.minus({ seconds: 1 });

const fmt = "yyyy-MM-dd'T'HH:mm:ssZZ";

// Filing rule: file by END DATE. A week straddling a month or year boundary
// files under the month it CLOSES in.
const year = weekEnd.toFormat('yyyy');
const month = weekEnd.toFormat('MM-MMMM');
const fileName = weekEnd.toFormat('yyyy-MM-dd') + '-weekly-sales.json';

return [{
  json: {
    start_date: weekStart.toFormat(fmt),
    end_date: weekEnd.toFormat(fmt),
    week_start_label: weekStart.toFormat('yyyy-MM-dd'),
    week_end_label: weekEnd.toFormat('yyyy-MM-dd'),
    file_path: `business-decisions-data/detailed-sales-report/${year}/${month}/${fileName}`,
    generated_at: now.toFormat(fmt)
  }
}];

// Build the weekly file: metadata, computed summary, and trimmed line items.
// Full raw payload is ~800KB per week; trimming keeps the repo manageable
// while retaining every field the inventory analyst needs.

const win = $('Build Window').first().json;
const sales = items.map(i => i.json);

const round = n => Math.round(n * 100) / 100;

const categories = {};
const cigars = {};
const lineItems = [];

let grossTotal = 0;

for (const sale of sales) {
  grossTotal += Number(sale.total || 0);

  for (const c of (sale.cart_items || [])) {
    const qty = Number(c.quantity || 0);
    const unit = Number(c.unit_price || 0);
    const cost = Number(c.cost_price || 0);
    const cat = c.category_name || '(uncategorized)';
    const revenue = unit * qty;
    const cogs = cost * qty;

    if (!categories[cat]) categories[cat] = { units: 0, revenue: 0, cost: 0, margin: 0 };
    categories[cat].units += qty;
    categories[cat].revenue += revenue;
    categories[cat].cost += cogs;
    categories[cat].margin += (revenue - cogs);

    if (cat === 'Cigars') {
      const key = c.item_number || c.item_id;
      if (!cigars[key]) {
        cigars[key] = { item_id: c.item_id, item_number: c.item_number, name: c.name, units: 0, revenue: 0, cost: 0, margin: 0 };
      }
      cigars[key].units += qty;
      cigars[key].revenue += revenue;
      cigars[key].cost += cogs;
      cigars[key].margin += (revenue - cogs);
    }

    lineItems.push({
      sale_id: sale.sale_id,
      sale_time: sale.sale_time,
      item_id: c.item_id,
      item_number: c.item_number,
      name: c.name,
      category_name: cat,
      quantity: qty,
      unit_price: unit,
      regular_price: Number(c.regular_price || 0),
      cost_price: cost,
      discount: Number(c.discount || 0)
    });
  }
}

for (const k of Object.keys(categories)) {
  categories[k].revenue = round(categories[k].revenue);
  categories[k].cost = round(categories[k].cost);
  categories[k].margin = round(categories[k].margin);
}
for (const k of Object.keys(cigars)) {
  cigars[k].revenue = round(cigars[k].revenue);
  cigars[k].cost = round(cigars[k].cost);
  cigars[k].margin = round(cigars[k].margin);
}

const cigarList = Object.values(cigars).sort((a, b) => b.units - a.units);

const payload = {
  meta: {
    report: 'detailed sales report',
    week_start: win.week_start_label,
    week_end: win.week_end_label,
    start_date: win.start_date,
    end_date: win.end_date,
    timezone: 'America/New_York',
    filed_by: 'end date',
    generated_at: win.generated_at,
    source: 'PHP Point of Sale /api/v1/sales'
  },
  summary: {
    transaction_count: sales.length,
    gross_total: round(grossTotal),
    distinct_cigar_skus: cigarList.length,
    categories
  },
  cigars: cigarList,
  line_items: lineItems
};

return [{
  json: {
    file_path: win.file_path,
    commit_message: `Weekly sales ${win.week_start_label} to ${win.week_end_label} (${sales.length} transactions)`,
    file_content: JSON.stringify(payload, null, 2)
  }
}];
